@layer base, components;
@layer components { .btn { color: blue; } }
@layer base { #app .btn { color: red; } }
.btn { color: green; }

.header  { position: relative; z-index: 1; }
.menu    { position: absolute; z-index: 9999; } /* in .header */
.content { position: relative; z-index: 2; }    /* after .header */

.row   { display: flex; }
.main  { flex: 1; }            /* contains .title */
.title { white-space: nowrap; overflow: hidden;
         text-overflow: ellipsis; }

.cards {
  display: grid;
  width: 1000px;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
}

.grid { display: grid; grid-template-columns: 1fr; }
@media (min-width: 1200px) {
  .grid { grid-template-columns: repeat(3, 1fr); }
}
@media (min-width: 768px) {
  .grid { grid-template-columns: 1fr 1fr; }
}

@layer reset {
  #app button.btn { color: red; }
}
.btn { color: blue; }

@layer base, components;
@layer components { .btn { color: blue; } }
@layer base { #app button.btn { color: red; } }

@layer base, theme;
@layer base  { .btn { color: red !important; } }
@layer theme { .btn { color: blue !important; } }

.badge {
  position: absolute;
  inset: 0;
  width: 200px;
  height: 100px;
  margin: auto;
}

.page {
  display: grid;
  grid-template-columns: 200px 1fr;
  grid-template-areas:
    "header header"
    "nav    main";
}

.grid {
  display: grid;
  gap: 20px;
  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
}

.btn { background: white; }
.btn:hover {
  background: gold;
  transition: background 0.3s;
}
